css:
#card { position:absolute; left:96px; bottom:150px; display:flex; align-items:stretch; }
#bar { width:12px; background:var(--red); transform-origin:bottom center; }
#txt { padding:6px 0 6px 26px; }
#name { font-weight:700; font-size:66px; line-height:1.05; text-transform:uppercase; text-shadow:0 4px 22px rgba(0,0,0,.75); }
#role { font-weight:400; font-size:38px; margin-top:8px; text-shadow:0 3px 16px rgba(0,0,0,.8); }
#role b { color:#fff; background:var(--red); font-weight:700; padding:2px 12px; margin-left:6px; }

js:
document.getElementById('name').textContent = V.actor;
const r = document.getElementById('role');
if (V.character) { r.textContent = 'as'; const b = document.createElement('b'); b.textContent = V.character; r.appendChild(b); }
const D = V.duration;
tl.fromTo('#bar', { scaleY: 0 }, { scaleY: 1, duration: 0.3, ease: 'power3.out' }, 0);
tl.fromTo('#name', { x: -40, opacity: 0 }, { x: 0, opacity: 1, duration: 0.4, ease: 'power3.out' }, 0.15);
tl.fromTo('#role', { x: -30, opacity: 0 }, { x: 0, opacity: 1, duration: 0.4, ease: 'power3.out' }, 0.3);
tl.to('#card', { opacity: 0, x: -30, duration: 0.35, ease: 'power2.in' }, D - 0.4);
